    "synopsis": "Following the massive operation that led to the confinement of recent recruit Kafka Hibino, otherwise known as Kaiju No. 8, the Defense Force has been puzzled by how to deal with him. Kafka is the first kaiju to side with humans, and after careful consideration, he is eventually transferred to the Defense Force's First Division in the hope of adding his power to the strongest division, capable of handling any threat. However, some people are still doubtful about Kafka, and he must prove his worth in the next mission. Kafka and the First Division are soon dispatched when a massive horde of ant-like kaiju begins wreaking havoc. Thanks to the combined strength of Kafka's friend Kikoru Shinomiya and their captain, Gen Narumi, the mission seems to progress as it should. However, when Kafka fails to transform into his kaiju form, the dreadful Kaiju No. 9 joins the battle with only one goal—to eliminate him and steal his power. Although the situation is looking grim, Kafka must overcome his most difficult trial yet with the others if he wants to keep pursuing his dream: fighting side by side with his childhood friend and Third Division captain, Mina Ashiro. (Source: MAL Rewrite)",
